N = dt.N
NPAIR = N * (N + 1) // 2
PI = np.pi


def log(msg: str) -> None:
    print(msg, flush=True)


# ---------------------------------------------------------------------------------------------
# Symmetric-pair basis


class Sym:
    """s(X)_I = X_pq * (sqrt2 if p < q else 1) for pairs I = (p <= q): <X, Y>_F = s(X).s(Y)."""

    def __init__(self):
        self.P, self.Q = np.triu_indices(N)
        self.scale = np.where(self.P == self.Q, 1.0, np.sqrt(2.0))
        self.idx = np.zeros((N, N), dtype=np.int64)
        self.idx[self.P, self.Q] = np.arange(NPAIR)
        self.idx[self.Q, self.P] = np.arange(NPAIR)

    def of_outer(self, u: np.ndarray) -> np.ndarray:
        """s(u u^T) for rows u (m, N) -> (m, NPAIR)."""
        return u[:, self.P] * u[:, self.Q] * self.scale

    def of_matrix(self, X: np.ndarray) -> np.ndarray:
        return X[..., self.P, self.Q] * self.scale

    def grad_outer(self, g: np.ndarray, u: np.ndarray) -> np.ndarray:
        """d <g, s(u u^T)> / du for rows: Gamma_pq = g_I * scale / 2 (off-diag) or g_I (diag); 2 Gamma u."""
        coef = g * np.where(self.P == self.Q, 1.0, self.scale / 2.0)
        G = coef[..., self.idx]  # (m, N, N) symmetric gather
        return 2.0 * np.matmul(G, u[..., :, None])[..., 0]

    def to_matrix(self, z: np.ndarray) -> np.ndarray:
        """Inverse of of_matrix for one vector z (NPAIR,) -> symmetric (N, N)."""
        X = np.zeros((N, N))
        X[self.P, self.Q] = z / self.scale
        X[self.Q, self.P] = z / self.scale
        return X


# ---------------------------------------------------------------------------------------------
# Givens chain, with the adjoint


def givens_forward(theta_over_pi: np.ndarray, edges: np.ndarray):
    """Decode rows of theta/pi into unit vectors, keeping the pre-rotation pairs for the adjoint."""
    m = theta_over_pi.shape[0]
    v = np.zeros((m, N))
    v[:, 0] = 1.0
    cs = np.cos(PI * theta_over_pi)
    sn = np.sin(PI * theta_over_pi)
    saved = np.empty((len(edges), 2, m))
    for t, (p, c) in enumerate(edges):
        vp, vc = v[:, p].copy(), v[:, c].copy()
        saved[t, 0], saved[t, 1] = vp, vc
        v[:, p] = cs[:, t] * vp - sn[:, t] * vc
        v[:, c] = sn[:, t] * vp + cs[:, t] * vc
    return v, (cs, sn, saved)


def givens_backward(g: np.ndarray, cache, edges: np.ndarray) -> np.ndarray:
    """dL/d(theta/pi) given dL/dv (m, N)."""
    cs, sn, saved = cache
    g = g.copy()
    dth = np.empty((g.shape[0], len(edges)))
    for t in range(len(edges) - 1, -1, -1):
        p, c = edges[t]
        vp, vc = saved[t]
        gp, gc = g[:, p].copy(), g[:, c].copy()
        dth[:, t] = gp * (-sn[:, t] * vp - cs[:, t] * vc) + gc * (cs[:, t] * vp - sn[:, t] * vc)
        g[:, p] = cs[:, t] * gp + sn[:, t] * gc
        g[:, c] = -sn[:, t] * gp + cs[:, t] * gc
    return dth * PI


# ---------------------------------------------------------------------------------------------
# The problem


class Problem:
    def __init__(self, ref: dict, fac: dt.Factorization):
        self.ref, self.fac = ref, fac
        self.sym = Sym()
        self.edges = fac.edges
        self.R, self.B, self.C = fac.w.shape
        self.Wmat = fac.W  # (R, C), fixed
        tei = ref["tei"]
        S = fac.S
        # Target in the pair basis: T_s[I(pq), I(rs)] = (tei + shift)[p,q,r,s] * scale_I * scale_J
        P, Q, sc = self.sym.P, self.sym.Q, self.sym.scale
        T = tei[P[:, None], Q[:, None], P[None, :], Q[None, :]].copy()  # (NPAIR, NPAIR)
        diag_pairs = np.where(P == Q)[0]
        # + 0.5 S[p,q] delta_rs  and  + 0.5 delta_pq S[r,s]
        T[:, diag_pairs] += 0.5 * S[P, Q][:, None]
        T[diag_pairs, :] += 0.5 * S[P, Q][None, :]
        self.T = T * sc[:, None] * sc[None, :]
        h1_thc = ref["oei"] - 0.5 * np.einsum("prrq->pq", tei)
        self.h1_base = h1_thc - 0.5 * ref["electrons"] * S + fac.beta_1 * np.eye(N)
        self.esos_const = ref["ecore"] - ref["electrons"] * fac.beta_1 - 0.5 * np.sum(fac.W ** 2)

    # -- pieces
    def lambda2(self, w: np.ndarray) -> float:
        return float(0.25 * np.sum((np.abs(w).sum(axis=1) + np.abs(self.Wmat + w.sum(axis=1))) ** 2))

    def lambda2_grad(self, w: np.ndarray) -> np.ndarray:
        wB = self.Wmat + w.sum(axis=1)
        tot = np.abs(w).sum(axis=1) + np.abs(wB)  # (R, C)
        return 0.5 * tot[:, None, :] * (np.sign(w) + np.sign(wB)[:, None, :])

    def h1_prime_from_M(self, M: np.ndarray, w: np.ndarray) -> np.ndarray:
        z = np.einsum("rc,rcs->s", self.Wmat, M.reshape(self.R, self.C, NPAIR))
        return self.h1_base - self.sym.to_matrix(z)

    negmass_target: float | None = None  # when set, the alpha term is alpha * (negmass - target)**2

    def negmass_for_egap(self, e_gap: float) -> float:
        """negmass that gives E_gap = e_gap (E_gap = E_UPPER - esos_const + 2 negmass)."""
        return 0.5 * (e_gap - (dt.E_UPPER - self.esos_const))

    def extra_dM(self, out: dict):
        """Hook: additional dL/dM (R*C, NPAIR) from subclass loss terms, or None."""
        return None

    def forward_backward(self, theta_q: np.ndarray, w: np.ndarray, alpha: float = 0.0, mu: float = 0.0,
                         need_grad: bool = True) -> dict:
        """Loss and gradients at quantised angles theta_q (theta/pi, (R*B, N-1)) and weights w.

        alpha weighs negmass linearly, or (negmass - negmass_target)**2 when `negmass_target` is set."""
        u, cache = givens_forward(theta_q, self.edges)
        out = self.forward_backward_u(u, w, alpha, mu, need_grad)
        if need_grad:
            out["dtheta"] = givens_backward(out["du"], cache, self.edges)
        return out

    def forward_backward_u(self, u: np.ndarray, w: np.ndarray, alpha: float = 0.0, mu: float = 0.0,
                           need_grad: bool = True) -> dict:
        """Same loss at point coordinates u (R*B, N) (rows need not be normalised: the verifier normalises;
        here they are used as given), gradient `du` instead of `dtheta`."""
        Us = self.sym.of_outer(u)  # (R*B, NPAIR)
        Usr = Us.reshape(self.R, self.B, NPAIR)
        M = np.matmul(w.transpose(0, 2, 1), Usr).reshape(self.R * self.C, NPAIR)
        Res = M.T @ M
        Res -= self.T
        L2 = float(np.sum(Res * Res))
        h1p = self.h1_prime_from_M(M, w)
        lam, V = np.linalg.eigh(h1p)
        neg = lam < 0
        negmass = float(-lam[neg].sum())
        lam1 = float(np.abs(lam).sum())
        lam2 = self.lambda2(w)
        Lambda = lam1 + lam2
        E_sos = self.esos_const - 2.0 * negmass
        E_gap = dt.E_UPPER - E_sos
        lam_eff = float(np.sqrt(E_gap * (2 * Lambda - E_gap))) if 0 < E_gap < 2 * Lambda else float("nan")
        if self.negmass_target is None:
            pen, alpha_lin = alpha * negmass, alpha
        else:
            pen = alpha * (negmass - self.negmass_target) ** 2
            alpha_lin = 2.0 * alpha * (negmass - self.negmass_target)
        out = {"L2": L2, "error_2": np.sqrt(L2), "negmass": negmass, "Lambda": Lambda, "E_gap": E_gap,
               "lambda_eff": lam_eff, "lambda2": lam2, "loss": L2 + pen + mu * lam2, "alpha_lin": alpha_lin,
               "u": u, "Us": Us, "M": M, "Res": Res, "lam": lam, "V": V}
        if not need_grad:
            return out
        dM = 4.0 * (M @ Res)  # (R*C, NPAIR)
        if alpha_lin:
            Pneg = V[:, neg] @ V[:, neg].T
            dM += alpha_lin * np.einsum("rc,s->rcs", self.Wmat, self.sym.of_matrix(Pneg)).reshape(self.R * self.C, NPAIR)
        extra = self.extra_dM(out)  # subclasses add loss terms that act through M (one adjoint pass)
        if extra is not None:
            dM += extra
        dMr = dM.reshape(self.R, self.C, NPAIR)
        dw = np.matmul(Usr, dMr.transpose(0, 2, 1))
        if mu:
            dw += mu * self.lambda2_grad(w)
        dUs = np.matmul(w, dMr).reshape(self.R * self.B, NPAIR)
        out["du"], out["dw"] = self.sym.grad_outer(dUs, u), dw
        return out


# ---------------------------------------------------------------------------------------------
# Words <-> latent angles, exact evaluation


def quantize_theta(theta: np.ndarray, brot: int) -> tuple[np.ndarray, np.ndarray]:
    words = dt.quantize(theta, brot)
    return words, words / (1 << (brot - 1))


def one_body_feedback(lam: np.ndarray, V: np.ndarray, brot: int, edges: np.ndarray, cap: float = 0.5,
                      total_cap: float = 0.6) -> np.ndarray:
    """Sequential error-feedback encoding of the eigenvectors (columns of V) as brot-bit words.

    To first order the one-body error is E_ab = lambda_a d_a[b] + lambda_b d_b[a] (d_j = v_j - e_j in the
    eigenbasis).  Encoding the rows in decreasing |lambda| and giving row b the target
    e_b - sum_{a done} (lambda_a / lambda_b) d_a[b] e_a cancels the error the earlier rows left in
    row/column b, so only lambda_min(a,b) * (rounding error) survives.  Corrections are clipped to +-cap per
    coordinate and total_cap in norm (the verifier must still match row b to e_b by overlap).
    """
    n = len(lam)
    order = np.argsort(-np.abs(lam))
    coords = np.zeros((n, n))  # v_j in the eigenbasis
    words = np.zeros((n, n - 1), dtype=np.int64)
    done = []
    for b in order:
        target = np.zeros(n)
        target[b] = 1.0
        if done and abs(lam[b]) > 1e-9:
            a = np.array(done)
            corr = -(lam[a] / lam[b]) * coords[a, b]
            corr = np.clip(corr, -cap, cap)
            nrm = np.linalg.norm(corr)
            if nrm > total_cap:
                corr *= total_cap / nrm
            target[a] = corr
        target /= np.linalg.norm(target)
        words[b] = dt.quantize(dt.decompose((V @ target)[None, :], edges), brot)[0]
        coords[b] = V.T @ dt.decode(words[b][None, :], brot, edges)[0]
        done.append(b)
    return words


def one_body_words(prob: Problem, words2: np.ndarray, w: np.ndarray, brot: int, sweeps: int = 2,
                   verbose: bool = True, feedback: bool = True) -> tuple[np.ndarray, float]:
    """Words of the 76 one-body rows for quantised two-body words: eigenvectors of h1' encoded with
    error feedback (or plain rounding, whichever is better), then coordinate descent on
    error_1 = ||sum_j lambda_j v_j v_j^T - h1'||_F (+-1, +-2 moves)."""
    fac = dt.Factorization(w=w, W=prob.Wmat, S=prob.fac.S, beta_1=prob.fac.beta_1, edges=prob.edges,
                           U=prob.fac.U, H1_I=prob.fac.H1_I, Hsym_lower=prob.fac.Hsym_lower)
    u2 = dt.decode(words2, brot, prob.edges).reshape(prob.R, prob.B, N)
    h1p = dt.h1_prime(prob.ref, fac, u2)
    lam, V = np.linalg.eigh(h1p)

    def err_of(words1):
        v = dt.decode(words1, brot, prob.edges)
        E = np.einsum("j,jp,jq->pq", lam, v, v) - h1p
        return v, E, float(np.linalg.norm(E))

    words1 = dt.quantize(dt.decompose(V.T, prob.edges), brot)
    v, E, err = err_of(words1)
    if verbose:
        print(f"  one-body: rounded error_1 {1e3*err:.3f} mHa", flush=True)
    if feedback:
        best = (err, words1, v, E)
        for cap, tcap in ((0.1, 0.2), (0.25, 0.4), (0.5, 0.6), (1.0, 0.9)):
            wf = one_body_feedback(lam, V, brot, prob.edges, cap=cap, total_cap=tcap)
            vf, Ef, ef = err_of(wf)
            if verbose:
                print(f"  one-body: feedback cap {cap}/{tcap} error_1 {1e3*ef:.3f} mHa", flush=True)
            if ef < best[0]:
                best = (ef, wf, vf, Ef)
        err, words1, v, E = best
    order = np.argsort(-np.abs(lam))
    modulus = 1 << brot
    for sweep in range(sweeps):
        improved = 0
        for j in order:
            if abs(lam[j]) < 1e-12:
                continue
            cand = np.repeat(words1[j][None, :], 4 * (N - 1), axis=0)
            t_idx = np.repeat(np.arange(N - 1), 4)
            d = np.tile(np.array([1, -1, 2, -2]), N - 1)
            cand[np.arange(len(cand)), t_idx] = (cand[np.arange(len(cand)), t_idx] + d) % modulus
            base = E - lam[j] * np.outer(v[j], v[j])
            # continuous retarget moves: v' = normalize(v_j - s/lam_j * P_perp base v_j) for a few step sizes,
            # rounded; the first-order optimum of ||base + lam_j v v^T|| near v_j
            g = base @ v[j]
            g -= (g @ v[j]) * v[j]
            targets = [v[j] - (sc / lam[j]) * g for sc in (0.25, 0.5, 0.75, 1.0, 1.5)]
            targets = np.array([t / np.linalg.norm(t) for t in targets])
            cand = np.concatenate([cand, dt.quantize(dt.decompose(targets, prob.edges), brot)], axis=0)
            vj_new = dt.decode(cand, brot, prob.edges)
            # ||base + lam_j v' v'^T||^2 = ||base||^2 + 2 lam_j v'^T base v' + lam_j^2
            quad = np.einsum("ip,pq,iq->i", vj_new, base, vj_new)
            vals = np.sum(base * base) + 2 * lam[j] * quad + lam[j] ** 2
            i = int(np.argmin(vals))
            if vals[i] < err ** 2 - 1e-14:
                words1[j] = cand[i]
                v[j] = vj_new[i]
                E = base + lam[j] * np.outer(v[j], v[j])
                err = float(np.sqrt(vals[i]))
                improved += 1
        if verbose:
            print(f"  one-body sweep {sweep}: {improved} moves, error_1 {1e3*err:.3f} mHa", flush=True)
        if not improved:
            break
    return words1, err


def exact_eval(prob: Problem, words2: np.ndarray, w: np.ndarray, brot: int, one_body_sweeps: int = 2,
               verbose: bool = False) -> tuple[dict, np.ndarray]:
    """Verifier metrics of the full word table with w rounded to float32 (as stored)."""
    w32 = np.asarray(np.asarray(w, dtype=np.float32), dtype=np.float64)
    words1, _ = one_body_words(prob, words2, w32, brot, sweeps=one_body_sweeps, verbose=verbose)
    words = np.concatenate([words1, words2], axis=0)
    fac = dt.Factorization(w=w32, W=prob.Wmat, S=prob.fac.S, beta_1=prob.fac.beta_1, edges=prob.edges,
                           U=prob.fac.U, H1_I=prob.fac.H1_I, Hsym_lower=prob.fac.Hsym_lower)
    # W is stored through H2_I = W + sum w in float32; mimic that rounding too
    H2_I = np.asarray(np.asarray(fac.W + w32.sum(axis=1), dtype=np.float32), dtype=np.float64)
    fac.W = H2_I - w32.sum(axis=1)
    return dt.evaluate_words(prob.ref, fac, words, brot), words


# ---------------------------------------------------------------------------------------------
# QAT (Adam + STE)


class Adam:
    def __init__(self, shape, lr, b1=0.9, b2=0.999, eps=1e-12):
        self.m, self.v, self.t = np.zeros(shape), np.zeros(shape), 0
        self.lr, self.b1, self.b2, self.eps = lr, b1, b2, eps

    def step(self, x, g):
        self.t += 1
        self.m = self.b1 * self.m + (1 - self.b1) * g
        self.v = self.b2 * self.v + (1 - self.b2) * g * g
        mh = self.m / (1 - self.b1 ** self.t)
        vh = self.v / (1 - self.b2 ** self.t)
        return x - self.lr * mh / (np.sqrt(vh) + self.eps)


def qat(prob: Problem, theta: np.ndarray, w: np.ndarray, brot: int | None, steps: int, lr_theta: float,
        lr_w: float, alpha: float = 0.0, mu: float = 0.0, eval_every: int = 50, log=log,
        lr_decay: float = 1.0) -> tuple[np.ndarray, np.ndarray, list]:
    """Adam on (latent theta/pi, w); the forward pass uses the brot-quantised angles (STE) when brot is set."""
    theta, w = theta.copy(), w.copy()
    opt_t, opt_w = Adam(theta.shape, lr_theta), Adam(w.shape, lr_w)
    history = []
    t0 = time.time()
    for step in range(steps + 1):
        theta_q = quantize_theta(theta, brot)[1] if brot else theta
        r = prob.forward_backward(theta_q, w, alpha, mu, need_grad=step < steps)
        if step % eval_every == 0 or step == steps:
            msg = (f"step {step:5d}  e2 {1e3*r['error_2']:8.3f} mHa  negmass {r['negmass']:.4f}  "
                   f"Lambda {r['Lambda']:.3f}  E_gap {r['E_gap']:.5f}  lam_eff {r['lambda_eff']:.4f}  "
                   f"loss {r['loss']:.6e}  ({time.time()-t0:.0f}s)")
            log(msg)
            history.append({k: r[k] for k in ("error_2", "negmass", "Lambda", "E_gap", "lambda_eff", "loss")})
        if step == steps:
            break
        theta = opt_t.step(theta, r["dtheta"])
        if lr_w > 0:
            w = opt_w.step(w, r["dw"])
        opt_t.lr *= lr_decay
        opt_w.lr *= lr_decay
    return theta, w, history


# ---------------------------------------------------------------------------------------------
# L-BFGS on the continuous variables (optionally with some vectors frozen at quantised words)

W_SCALE = 2.5e-3  # typical |w|: L-BFGS sees w / W_SCALE so that angle and weight coordinates are comparable


def lbfgs(prob: Problem, theta: np.ndarray, w: np.ndarray, *, opt_theta: bool = True, opt_w: bool = True,
          frozen: np.ndarray | None = None, alpha: float = 0.0, mu: float = 0.0, maxiter: int = 200,
          log=log, tag: str = "") -> tuple[np.ndarray, np.ndarray, dict]:
    """Minimise loss over the continuous theta (rows not in `frozen`) and/or w with scipy L-BFGS-B.

    `frozen` is a boolean mask over the R*B two-body rows whose theta stay fixed (already quantised)."""
    from scipy.optimize import minimize

    theta0, w0 = theta.copy(), w.copy()
    free = np.ones(theta.shape[0], dtype=bool) if frozen is None else ~frozen
    n_t = int(free.sum()) * theta.shape[1] if opt_theta else 0
    n_w = w.size if opt_w else 0
    x0 = np.concatenate([theta0[free].ravel() if opt_theta else np.empty(0), (w0 / W_SCALE).ravel() if opt_w else np.empty(0)])
    state = {"calls": 0, "t0": time.time(), "best": None}

    def unpack(x):
        th = theta0.copy()
        if opt_theta:
            th[free] = x[:n_t].reshape(-1, theta.shape[1])
        ww = w0 if not opt_w else x[n_t:].reshape(w.shape) * W_SCALE
        return th, ww

    def fun(x):
        th, ww = unpack(x)
        r = prob.forward_backward(th, ww, alpha, mu)
        state["calls"] += 1
        g = []
        if opt_theta:
            g.append(r["dtheta"][free].ravel())
        if opt_w:
            g.append((r["dw"] * W_SCALE).ravel())
        if state["calls"] % 25 == 1:
            log(f"  lbfgs{tag} call {state['calls']:4d}  e2 {1e3*r['error_2']:8.3f} mHa  negmass {r['negmass']:.4f}  "
                f"Lambda {r['Lambda']:.3f}  lam_eff {r['lambda_eff']:.4f}  ({time.time()-state['t0']:.0f}s)")
        return r["loss"], np.concatenate(g)

    res = minimize(fun, x0, jac=True, method="L-BFGS-B", options={"maxiter": maxiter, "maxcor": 20, "ftol": 1e-14, "gtol": 1e-12})
    th, ww = unpack(res.x)
    r = prob.forward_backward(th, ww, alpha, mu, need_grad=False)
    log(f"  lbfgs{tag} done ({res.nit} it, {state['calls']} calls, {res.message}): e2 {1e3*r['error_2']:.3f} mHa  "
        f"negmass {r['negmass']:.4f}  Lambda {r['Lambda']:.3f}  lam_eff {r['lambda_eff']:.4f}")
    return th, ww, r


def progressive(prob: Problem, theta: np.ndarray, w: np.ndarray, brot: int, batches: int = 16,
                iters: int = 30, alpha: float = 0.0, mu: float = 0.0, seed: int = 0, log=log,
                final_iters: int = 100) -> tuple[np.ndarray, np.ndarray]:
    """Progressive quantisation: freeze the rows batch by batch at their rounded words and re-optimise
    the still-continuous rows and the weights after each batch (error diffusion across vectors)."""
    theta, w = theta.copy(), w.copy()
    m = theta.shape[0]
    rng = np.random.default_rng(seed)
    perm = rng.permutation(m)
    frozen = np.zeros(m, dtype=bool)
    for k, rows in enumerate(np.array_split(perm, batches)):
        theta[rows] = quantize_theta(theta[rows], brot)[1]
        frozen[rows] = True
        r = prob.forward_backward(theta, w, alpha, mu, need_grad=False)
        log(f"progressive batch {k+1}/{batches}: frozen {frozen.sum()}  e2 after rounding {1e3*r['error_2']:.3f} mHa")
        last = frozen.all()
        theta, w, r = lbfgs(prob, theta, w, opt_theta=not last, opt_w=True, frozen=frozen, alpha=alpha, mu=mu,
                            maxiter=final_iters if last else iters, log=log, tag=f"[prog {k+1}]")
    return theta, w


def refine(prob: Problem, theta: np.ndarray, w: np.ndarray, brot: int, rounds: int = 8, fraction: float = 0.125,
           sub_batches: int = 4, iters_free: int = 30, iters_sub: int = 15, alpha: float = 0.0, mu: float = 0.0,
           seed: int = 1, log=log) -> tuple[np.ndarray, np.ndarray]:
    """Unfreeze/refreeze rounds on words already on the grid: a random `fraction` of the rows is made
    continuous and re-optimised (with w) against all the frozen rows, then frozen again progressively."""
    theta, w = theta.copy(), w.copy()
    m = theta.shape[0]
    rng = np.random.default_rng(seed)
    for rnd in range(rounds):
        rows = rng.choice(m, int(fraction * m), replace=False)
        frozen = np.ones(m, dtype=bool)
        frozen[rows] = False
        theta, w, r = lbfgs(prob, theta, w, opt_theta=True, opt_w=True, frozen=frozen, alpha=alpha, mu=mu,
                            maxiter=iters_free, log=log, tag=f"[refine {rnd+1} free]")
        for k, sub in enumerate(np.array_split(rng.permutation(rows), sub_batches)):
            theta[sub] = quantize_theta(theta[sub], brot)[1]
            frozen[sub] = True
            last = frozen.all()
            theta, w, r = lbfgs(prob, theta, w, opt_theta=not last, opt_w=True, frozen=frozen, alpha=alpha, mu=mu,
                                maxiter=iters_sub, log=log, tag=f"[refine {rnd+1}.{k+1}]")
        log(f"refine round {rnd+1}/{rounds}: e2 {1e3*r['error_2']:.3f} mHa  lam_eff {r['lambda_eff']:.4f}")
    return theta, w


# ---------------------------------------------------------------------------------------------
# Exact coordinate descent on the two-body words


def polish(prob: Problem, words2: np.ndarray, w: np.ndarray, brot: int, sweeps: int = 1, alpha: float = 0.0,
           moves=(1, -1), log=log, order_seed: int = 0, max_moves: int = 1) -> np.ndarray:
    """Greedy best single-word move per vector per sweep (up to `max_moves` accepted in a row per vector),
    scored with the exact change of error_2^2 (plus alpha * first-order change of negmass)."""
    words2 = words2.copy()
    modulus = 1 << brot
    sym = prob.sym
    theta_q = words2 / (1 << (brot - 1))
    r = prob.forward_backward(theta_q, w, alpha, 0.0, need_grad=False)
    Us, M, Res = r["Us"], r["M"].reshape(prob.R, prob.C, NPAIR), r["Res"]
    L2 = r["L2"]
    log(f"polish start: e2 {1e3*np.sqrt(L2):.3f} mHa")
    rng = np.random.default_rng(order_seed)
    nm = len(moves)
    t_idx = np.repeat(np.arange(N - 1), nm)
    d_arr = np.tile(np.array(moves), N - 1)
    ncand = len(t_idx)
    for sweep in range(sweeps):
        t0 = time.time()
        # refresh P_neg for the first-order negmass term
        neg_vec, alpha_lin = None, 0.0

        def relinearise():
            # first-order negmass term; with a quadratic target the coefficient depends on the current negmass,
            # so it is refreshed every 200 vectors (a stale coefficient lets the sweep trade error for penalty)
            h1p = prob.h1_prime_from_M(M.reshape(prob.R * prob.C, NPAIR), w)
            lam, V = np.linalg.eigh(h1p)
            negmass = float(-lam[lam < 0].sum())
            return (sym.of_matrix(V[:, lam < 0] @ V[:, lam < 0].T),
                    alpha if prob.negmass_target is None else 2.0 * alpha * (negmass - prob.negmass_target))

        accepted, gain = 0, 0.0
        for ib, b in enumerate(rng.permutation(prob.R * prob.B)):
          if alpha and ib % 200 == 0:
              neg_vec, alpha_lin = relinearise()
          for _rep in range(max_moves):
            rho, bb = divmod(b, prob.B)
            wb = w[rho, bb, :]  # (C,)
            y = wb @ M[rho]  # (NPAIR,) = sum_c w_bc M[rho, c]
            k = float(wb @ wb)
            cand = np.repeat(words2[b][None, :], ncand, axis=0)
            cand[np.arange(ncand), t_idx] = (cand[np.arange(ncand), t_idx] + d_arr) % modulus
            u_new = dt.decode(cand, brot, prob.edges)
            delta = sym.of_outer(u_new) - Us[b][None, :]  # (ncand, NPAIR)
            RD = Res @ delta.T  # (NPAIR, ncand)
            yRd = y @ RD
            dRd = np.einsum("is,si->i", delta, RD)
            yd = delta @ y
            dd = np.einsum("is,is->i", delta, delta)
            yy = float(y @ y)
            dH2 = 2 * yy * dd + 2 * yd ** 2 + k * k * dd ** 2 + 4 * k * yd * dd
            dL = 4 * yRd + 2 * k * dRd + dH2
            if alpha_lin:
                dL = dL + alpha_lin * float(prob.Wmat[rho] @ wb) * (delta @ neg_vec)
            i = int(np.argmin(dL))
            if dL[i] >= -1e-15:
                break
            dlt = delta[i]
            words2[b] = cand[i]
            Us[b] += dlt
            M[rho] += np.outer(wb, dlt)
            Res += np.outer(y, dlt) + np.outer(dlt, y) + k * np.outer(dlt, dlt)
            L2 += 4 * yRd[i] + 2 * k * dRd[i] + dH2[i]
            accepted += 1
            gain += dL[i]
        log(f"polish sweep {sweep}: {accepted} moves, e2 {1e3*np.sqrt(max(L2, 0)):.3f} mHa "
            f"(dL {gain:.3e}, {time.time()-t0:.0f}s)")
        if not accepted:
            break
    # recompute exactly (the incremental L2 accumulates rounding)
    r = prob.forward_backward(words2 / (1 << (brot - 1)), w, need_grad=False)
    log(f"polish end: e2 {1e3*r['error_2']:.3f} mHa  negmass {r['negmass']:.4f}  lam_eff {r['lambda_eff']:.4f}")
    return words2


# ---------------------------------------------------------------------------------------------
# State files


def save_state(path: str, prob: Problem, theta: np.ndarray, w: np.ndarray, brot: int, words: np.ndarray | None,
               metrics: dict | None) -> None:
    arrays = {"theta": theta, "w": w, "brot": np.int64(brot)}
    if words is not None:
        arrays["angle_words"] = words
        u_all = dt.decode(words, brot, prob.edges)
        sub = prob.fac.npz_arrays(U=u_all[N:].reshape(prob.R, prob.B, N), angle_words=words)
        sub["W"] = np.asarray(w, dtype=np.float32)
        sub["H2_I"] = np.asarray(prob.fac.W + w.sum(axis=1), dtype=np.float32)
        sub["U"] = np.asarray(sub["U"], dtype=np.float32)
        arrays.update({f"sub_{k}": v for k, v in sub.items()})
    if metrics is not None:
        arrays.update({f"metric_{k}": np.float64(v) for k, v in metrics.items() if k != "gap_in_domain"})
    np.savez(path, **arrays)


def write_submission_npz(state_path: str, out_path: str) -> dict:
    with np.load(state_path) as z:
        sub = {k[4:]: z[k] for k in z.files if k.startswith("sub_")}
    np.savez(out_path, **sub)
    return sub


def load_state(path: str):
    with np.load(path) as z:
        return z["theta"], z["w"], int(z["brot"])


# ---------------------------------------------------------------------------------------------


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--brot", type=int, required=True)
    ap.add_argument("--init", default=None, help="state .npz from an earlier run (default: the baseline)")
    ap.add_argument("--mode", choices=("prog", "refine", "qat", "polish", "wfit", "eval"), default="prog")
    ap.add_argument("--rounds", type=int, default=8, help="refine: unfreeze/refreeze rounds")
    ap.add_argument("--fraction", type=float, default=0.125, help="refine: fraction of rows per round")
    ap.add_argument("--batches", type=int, default=16, help="prog: number of freeze batches")
    ap.add_argument("--iters", type=int, default=30, help="prog: L-BFGS iterations per batch; wfit: iterations")
    ap.add_argument("--steps", type=int, default=300, help="qat: Adam steps")
    ap.add_argument("--lr-theta", type=float, default=1e-5)
    ap.add_argument("--lr-w", type=float, default=1e-7)
    ap.add_argument("--alpha", type=float, default=0.0, help="weight of negmass(h1') in the loss")
    ap.add_argument("--mu", type=float, default=0.0, help="weight of Lambda_2 in the loss")
    ap.add_argument("--egap-target", type=float, default=None,
                    help="steer E_gap to this value (Ha, > 3.914898): alpha then weighs (negmass - target)^2")
    ap.add_argument("--polish", type=int, default=0, help="coordinate-descent sweeps (after the main phase)")
    ap.add_argument("--polish-rounds", type=int, default=1, help="rounds of (polish sweeps + w refit)")
    ap.add_argument("--polish-alpha", type=float, default=None, help="polish: negmass weight (default: --alpha)")
    ap.add_argument("--polish-moves", type=int, default=1, help="polish: word deltas +-1..+-this")
    ap.add_argument("--polish-max-moves", type=int, default=1, help="polish: accepted moves in a row per vector")
    ap.add_argument("--one-body-sweeps", type=int, default=3)
    ap.add_argument("--out", required=True)
    args = ap.parse_args()

    t0 = time.time()
    ref = dt.load_reference_cached()
    fac, base_words = dt.load_baseline()
    prob = Problem(ref, fac)
    if args.init:
        theta, w, _ = load_state(args.init)
    else:
        theta = dt.decompose(fac.U.reshape(-1, N), fac.edges)
        w = fac.w.copy()
    brot = args.brot
    if args.egap_target is not None:
        prob.negmass_target = prob.negmass_for_egap(args.egap_target)
        log(f"E_gap target {args.egap_target} -> negmass target {prob.negmass_target:.6f}")
    words2 = quantize_theta(theta, brot)[0]
    m, _ = exact_eval(prob, words2, w, brot, one_body_sweeps=0)
    log(f"start (plain rounding of init): {dt.fmt(m)}")

    if args.mode == "prog":
        theta, w = progressive(prob, theta, w, brot, batches=args.batches, iters=args.iters, alpha=args.alpha, mu=args.mu)
        words2 = quantize_theta(theta, brot)[0]
    elif args.mode == "refine":
        theta = quantize_theta(theta, brot)[1]
        theta, w = refine(prob, theta, w, brot, rounds=args.rounds, fraction=args.fraction, iters_free=args.iters,
                          iters_sub=max(10, args.iters // 2), alpha=args.alpha, mu=args.mu)
        words2 = quantize_theta(theta, brot)[0]
    elif args.mode == "qat":
        theta, w, _ = qat(prob, theta, w, brot, args.steps, args.lr_theta, args.lr_w, args.alpha, args.mu)
        words2 = quantize_theta(theta, brot)[0]
    elif args.mode == "wfit":
        theta = quantize_theta(theta, brot)[1]
        theta, w, _ = lbfgs(prob, theta, w, opt_theta=False, opt_w=True, alpha=args.alpha, mu=args.mu, maxiter=args.iters, tag="[wfit]")
        words2 = quantize_theta(theta, brot)[0]
    if args.mode != "eval":
        m, _ = exact_eval(prob, words2, w, brot, one_body_sweeps=0)
        log(f"after {args.mode}: {dt.fmt(m)}")
    for rnd in range(args.polish_rounds if args.polish else 0):
        mv = tuple(d for k in range(1, args.polish_moves + 1) for d in (k, -k))
        pa = args.alpha if args.polish_alpha is None else args.polish_alpha
        words2 = polish(prob, words2, w, brot, sweeps=args.polish, alpha=pa, moves=mv, max_moves=args.polish_max_moves)
        theta = words2 / (1 << (brot - 1))
        theta, w, _ = lbfgs(prob, theta, w, opt_theta=False, opt_w=True, alpha=args.alpha, mu=args.mu, maxiter=args.iters, tag=f"[w after polish {rnd}]")
        m, _ = exact_eval(prob, words2, w, brot, one_body_sweeps=0)
        log(f"after polish round {rnd}: {dt.fmt(m)}")
    m, words = exact_eval(prob, words2, w, brot, one_body_sweeps=args.one_body_sweeps, verbose=True)
    log(f"final: {dt.fmt(m)}")
    save_state(args.out, prob, theta, w, brot, words, m)
    log(f"saved {args.out}  ({time.time()-t0:.0f}s total)")




# ======================================================================
# thc_fit.py
# ======================================================================

"""Single-group THC-style factorisation of FeMoCo76o113e for the dfthcsos task.

The verifier accepts any (R, B, C). With R = 1 the two-body operator is tensor hypercontraction,
H = U Z U^T with U = [s(u_b u_b^T)]_b (2,926 pairs x B) and Z = w w^T (B x B, rank <= C), and the family
loads only 76 + B vectors instead of 3,976: the ANGLES Toffolis and the inner PREPARE both shrink with B and C
(cost model in notes.md §7). The public frontier (self-reported) is R 1 / B 496 / C 384.

Pieces:
  * `THCProblem(Problem)`: free identity offsets W (C,) with the E_gap formula
        E_gap = E_UPPER - ecore + eta beta_1 + 0.5 sum W^2 + 2 negmass(h1'),
    loss = error_2^2 + a_gap (E_gap - target)^2 + mu Lambda_2 (+ alpha negmass), gradients for theta, w, W.
  * `init_dyads`: starting points from the eigen-structure of the target: the eigen-matrices V_k of T
    (2,926 x 2,926 PSD, rank ~400 at 5 mHa) are decomposed, their eigenvector dyads e e^T ranked by
    sigma_k lambda_i^2 and the top B distinct directions kept.
  * `solve_Z`: for fixed points the best Z is the projection (U^T U)^-1 U^T T U (U^T U)^-1; its PSD rank-C
    truncation gives w.
  * `fit`: alternate solve_Z with L-BFGS on (theta, w, W).
"""

import argparse
import os
import sys
import time

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

N = dt.N
NPAIR = rf.NPAIR
E_GAP_FLOOR = 3.914898
log = rf.log


class THCProblem(rf.Problem):
    """refit.Problem with free offsets W and the E_gap / Lambda terms of the score in the loss."""

    def __init__(self, ref, fac, a_gap: float = 0.0, egap_target: float = 3.918):
        super().__init__(ref, fac)
        self.a_gap, self.egap_target = a_gap, egap_target
        self.c_gap = ref["ecore"] - ref["electrons"] * fac.beta_1  # E_sos = c_gap - 0.5 sum W^2 - 2 negmass

    def set_W(self, W: np.ndarray) -> None:
        self.Wmat = np.asarray(W, dtype=np.float64).reshape(self.R, self.C)
        self.esos_const = self.c_gap - 0.5 * float(np.sum(self.Wmat ** 2))

    def forward_backward_u(self, u, w, alpha=0.0, mu=0.0, need_grad=True, W=None):
        if W is not None:
            self.set_W(W)
        w_shape = w.shape
        w = w.reshape(self.R, self.B, self.C)
        r = super().forward_backward_u(u, w, alpha, mu, need_grad)
        if need_grad:
            r["dw"] = r["dw"].reshape(w_shape)
        return self._extra_terms(r, u, w, w_shape, mu, need_grad, W, theta_q=None)

    def forward_backward(self, theta_q, w, alpha=0.0, mu=0.0, need_grad=True, W=None):
        if W is not None:
            self.set_W(W)
        w_shape = w.shape
        w = w.reshape(self.R, self.B, self.C)
        r = super().forward_backward(theta_q, w, alpha, mu, need_grad)
        if need_grad:
            r["dw"] = r["dw"].reshape(w_shape)
        return self._extra_terms(r, r["u"], w, w_shape, mu, need_grad, W, theta_q=theta_q)

    def extra_dM(self, out):
        if not self.a_gap or not np.isfinite(out["E_gap"]):
            return None
        dgap = out["E_gap"] - self.egap_target
        a_lin = 2.0 * self.a_gap * dgap * 2.0  # dL/dE_gap * dE_gap/dnegmass
        lam, V = out["lam"], out["V"]
        neg = lam < 0
        sP = self.sym.of_matrix(V[:, neg] @ V[:, neg].T)
        return a_lin * np.einsum("rc,s->rcs", self.Wmat, sP).reshape(self.R * self.C, NPAIR)

    def _extra_terms(self, r, u, w, w_shape, mu, need_grad, W, theta_q):
        if self.a_gap:
            dgap = r["E_gap"] - self.egap_target
            r["loss"] += self.a_gap * dgap * dgap
        if not need_grad:
            return r
        # gradients of the E_gap term: through negmass (as alpha_lin) and directly through W
        Wm = self.Wmat
        M = r["M"].reshape(self.R, self.C, NPAIR)
        lam, V = r["lam"], r["V"]
        neg = lam < 0
        sP = self.sym.of_matrix(V[:, neg] @ V[:, neg].T)  # s(P_neg)
        dnm_dW = np.einsum("rcs,s->rc", M, sP)  # d negmass / d W_rc = <P_neg, X_rc>
        dW = np.zeros_like(Wm)
        if self.a_gap:
            dgap = r["E_gap"] - self.egap_target
            coef = 2.0 * self.a_gap * dgap  # dL/dE_gap
            dW += coef * (Wm + 2.0 * dnm_dW)  # the negmass part through M is in extra_dM
        if mu:
            wB = Wm + w.sum(axis=1)
            tot = np.abs(w).sum(axis=1) + np.abs(wB)
            dW += mu * 0.5 * tot * np.sign(wB)
        r["dW"] = dW.reshape(self.Wmat.shape if W is None else np.shape(W))
        return r


# ---------------------------------------------------------------------------------------------


def target_eig(prob, k: int):
    ev, V = np.linalg.eigh(prob.T)
    idx = np.argsort(-ev)[:k]
    return ev[idx], V[:, idx]


def init_dyads(prob, B: int, k_factors: int = 400, dedupe: float = 0.98, seed: int = 0) -> np.ndarray:
    """B unit vectors: dominant eigenvector dyads of the top eigen-matrices of T."""
    sig, V = target_eig(prob, k_factors)
    cands, scores = [], []
    for k in range(k_factors):
        Vk = prob.sym.to_matrix(V[:, k])
        lam, E = np.linalg.eigh(Vk)
        for i in range(N):
            cands.append(E[:, i])
            scores.append(sig[k] * lam[i] ** 2)
    cands, scores = np.array(cands), np.array(scores)
    order = np.argsort(-scores)
    chosen = []
    for i in order:
        c = cands[i]
        if chosen and np.max(np.abs(np.array(chosen) @ c)) > dedupe:
            continue
        chosen.append(c)
        if len(chosen) == B:
            break
    return np.array(chosen)


def solve_Z(prob, u: np.ndarray, C: int):
    """Least-squares Z for fixed points, its PSD rank-C factor w (B, C) and the two errors."""
    Us = prob.sym.of_outer(u)  # (B, NPAIR)
    Q, Rm = np.linalg.qr(Us.T)  # Us.T = Q R, Q (NPAIR, B)
    TQ = prob.T @ Q
    core = Q.T @ TQ  # (B, B)
    err_free = np.sqrt(max(np.sum(prob.T ** 2) - np.sum(core ** 2), 0.0))  # ||T - P T P||^2 = ||T||^2 - ||Q^T T Q||^2
    Rinv = np.linalg.inv(Rm)
    Z = Rinv @ core @ Rinv.T
    Z = 0.5 * (Z + Z.T)
    lam, E = np.linalg.eigh(Z)
    idx = np.argsort(-lam)[:C]
    lam_c = np.clip(lam[idx], 0, None)
    w = E[:, idx] * np.sqrt(lam_c)[None, :]
    H = (Us.T @ w) @ (w.T @ Us)
    err_c = float(np.linalg.norm(H - prob.T))
    return w, err_free, err_c, lam


def make_fac(base: dt.Factorization, w: np.ndarray, W: np.ndarray, u: np.ndarray) -> dt.Factorization:
    B, C = w.shape
    return dt.Factorization(w=w.reshape(1, B, C), W=W.reshape(1, C), S=base.S, beta_1=base.beta_1, edges=base.edges,
                            U=u.reshape(1, B, N), H1_I=base.H1_I, Hsym_lower=base.Hsym_lower)


def lbfgs_thc(prob: THCProblem, theta, w, W, *, opt_theta=True, opt_w=True, opt_W=True, alpha=0.0, mu=0.0,
              maxiter=200, tag=""):
    from scipy.optimize import minimize

    shapes = {"theta": theta.shape, "w": w.shape, "W": W.shape}
    parts = []
    if opt_theta:
        parts.append(("theta", theta.ravel(), 1.0))
    if opt_w:
        parts.append(("w", (w / rf.W_SCALE).ravel(), rf.W_SCALE))
    if opt_W:
        parts.append(("W", W.ravel(), 1.0))
    x0 = np.concatenate([p[1] for p in parts])
    state = {"calls": 0, "t0": time.time()}

    def unpack(x):
        vals = {"theta": theta, "w": w, "W": W}
        off = 0
        for name, arr, scale in parts:
            vals[name] = x[off:off + arr.size].reshape(shapes[name]) * scale
            off += arr.size
        return vals

    def fun(x):
        v = unpack(x)
        r = prob.forward_backward(v["theta"], v["w"], alpha, mu, True, W=v["W"])
        state["calls"] += 1
        g = []
        for name, arr, scale in parts:
            g.append((r["d" + name] * scale).ravel())
        if state["calls"] % 50 == 1:
            log(f"  lbfgs{tag} call {state['calls']:5d}  e2 {1e3*r['error_2']:8.3f} mHa  E_gap {r['E_gap']:.5f}  "
                f"Lambda {r['Lambda']:.3f}  lam_eff {r['lambda_eff']:.4f}  ({time.time()-state['t0']:.0f}s)")
        return r["loss"], np.concatenate(g)

    res = minimize(fun, x0, jac=True, method="L-BFGS-B", options={"maxiter": maxiter, "maxcor": 30, "ftol": 1e-15, "gtol": 1e-13})
    v = unpack(res.x)
    r = prob.forward_backward(v["theta"], v["w"], alpha, mu, False, W=v["W"])
    log(f"  lbfgs{tag} done ({res.nit} it, {state['calls']} calls): e2 {1e3*r['error_2']:.3f} mHa  E_gap {r['E_gap']:.5f}  "
        f"Lambda {r['Lambda']:.3f}  lam_eff {r['lambda_eff']:.4f}")
    return v["theta"], v["w"], v["W"], r


# ---------------------------------------------------------------------------------------------
# Variable projection on the points: f(u) = min_Z ||U Z U^T - T||^2 with Z eliminated exactly.
# At the optimal Z the partial derivative in Z vanishes, so df/dU is the ordinary gradient with Z = Z*(U)
# (Golub-Pereyra); Z* = A T A^T with A = (U^T U)^-1 U^T is PSD because T is, so no truncation is involved.


def varpro_value_grad(prob, theta: np.ndarray, ridge: float = 0.0):
    u, cache = rf.givens_forward(theta, prob.edges)
    Us = prob.sym.of_outer(u)  # (B, NPAIR)
    Q, Rm = np.linalg.qr(Us.T)  # (NPAIR, B), (B, B)
    TQ = prob.T @ Q
    core = Q.T @ TQ
    f = float(np.sum(prob.T * prob.T) - np.sum(core * core))  # ||T - P T P||^2, P = Q Q^T
    # Z* = R^-1 core R^-T ; residual Res = Q core Q^T - T ; dL/dUs = 4 Z* Us Res
    Rinv = np.linalg.inv(Rm)
    Z = Rinv @ core @ Rinv.T
    ZUs = Z @ Us  # (B, NPAIR)
    # Res @ ZUs^T without forming Res: (Q core Q^T - T) ZUs^T = Q core (Q^T ZUs^T) - T ZUs^T
    QtZ = Q.T @ ZUs.T  # (B, B)
    dUs = 4.0 * (Q @ (core @ QtZ) - prob.T @ ZUs.T).T  # (B, NPAIR)
    du = prob.sym.grad_outer(dUs, u)
    dtheta = rf.givens_backward(du, cache, prob.edges)
    return f, dtheta, Z


def varpro_points(prob, theta: np.ndarray, maxiter: int = 500, tag: str = "", log=log):
    from scipy.optimize import minimize

    shape = theta.shape
    state = {"calls": 0, "t0": time.time()}

    def fun(x):
        f, g, _ = varpro_value_grad(prob, x.reshape(shape))
        state["calls"] += 1
        if state["calls"] % 50 == 1:
            log(f"  varpro{tag} call {state['calls']:5d}  projection error {1e3*np.sqrt(max(f, 0)):8.3f} mHa  ({time.time()-state['t0']:.0f}s)")
        return f, g.ravel()

    res = minimize(fun, theta.ravel(), jac=True, method="L-BFGS-B",
                   options={"maxiter": maxiter, "maxcor": 30, "ftol": 1e-15, "gtol": 1e-13})
    theta = res.x.reshape(shape)
    f, _, Z = varpro_value_grad(prob, theta)
    log(f"  varpro{tag} done ({res.nit} it, {state['calls']} calls, {res.message}): projection error {1e3*np.sqrt(max(f, 0)):.3f} mHa")
    return theta, Z, float(np.sqrt(max(f, 0)))


def init_isdf(prob, B: int, k_factors: int = 450, seed: int = 0) -> np.ndarray:
    """ISDF-style points without a grid: candidate 'grid points' are the eigenvectors of the dominant
    eigen-matrices of T; the B of them whose dyads best span the dominant pair space are chosen by a
    column-pivoted QR of G = diag(sqrt(sigma)) V^T D, D = [s(e e^T)] over the candidates."""
    from scipy.linalg import qr

    sig, V = target_eig(prob, k_factors)
    cands = []
    for k in range(k_factors):
        lam, E = np.linalg.eigh(prob.sym.to_matrix(V[:, k]))
        cands.append(E.T)  # rows: eigenvectors
    cands = np.concatenate(cands, axis=0)  # (k_factors * N, N)
    D = prob.sym.of_outer(cands)  # (ncand, NPAIR)
    G = (np.sqrt(np.clip(sig, 0, None))[:, None] * V.T) @ D.T  # (k_factors, ncand)
    _, _, piv = qr(G, mode="economic", pivoting=True)
    chosen = []
    for i in piv:
        c = cands[i]
        if chosen and np.max(np.abs(np.array(chosen) @ c)) > 0.999:
            continue
        chosen.append(c)
        if len(chosen) == B:
            break
    return np.array(chosen)


def projection_error(prob, u: np.ndarray) -> float:
    Us = prob.sym.of_outer(u)
    Q, _ = np.linalg.qr(Us.T)
    core = Q.T @ (prob.T @ Q)
    return float(np.sqrt(max(np.sum(prob.T ** 2) - np.sum(core ** 2), 0.0)))


# ---------------------------------------------------------------------------------------------
# From points to a submission: weights, offsets, quantised words


def weights_from_Z(Z: np.ndarray, C: int) -> np.ndarray:
    lam, E = np.linalg.eigh(Z)
    idx = np.argsort(-lam)[:C]
    return E[:, idx] * np.sqrt(np.clip(lam[idx], 0, None))[None, :]


def solve_offsets(prob: THCProblem, theta: np.ndarray, w: np.ndarray, W0: np.ndarray, *, egap_target: float = 3.918,
                  a_gap: float = 10.0, mu: float = 0.0, iters: int = 300, tag: str = "[W]"):
    """Offsets W for fixed points/weights: minimise a_gap (E_gap - target)^2 + mu Lambda_2 (the error does not
    depend on W).  Start: least squares W with sum_c W_c X^c ~ h1_base (negmass ~ 0), then L-BFGS."""
    prob.a_gap, prob.egap_target = a_gap, egap_target
    th, ww, W, r = lbfgs_thc(prob, theta, w, W0, opt_theta=False, opt_w=False, opt_W=True, mu=mu, maxiter=iters, tag=tag)
    return W, r


def ls_offsets(prob: THCProblem, u: np.ndarray, w: np.ndarray, frac: float = 1.0) -> np.ndarray:
    """Least-squares W with sum_c W_c X^c ~ frac * h1_base (in the pair basis)."""
    Us = prob.sym.of_outer(u)
    M = (w.T @ Us)  # (C, NPAIR) = s(X^c)
    target = prob.sym.of_matrix(prob.h1_base) * frac
    W, *_ = np.linalg.lstsq(M.T, target, rcond=None)
    return W


def submission_arrays(base: dt.Factorization, u: np.ndarray, w: np.ndarray, W: np.ndarray, words: np.ndarray) -> dict:
    B, C = w.shape
    return {
        "U": np.asarray(u.reshape(1, B, N), dtype=np.float32),
        "W": np.asarray(w.reshape(1, B, C), dtype=np.float32),
        "H2_I": np.asarray((W + w.sum(axis=0)).reshape(1, C), dtype=np.float32),
        "H1_I": np.asarray(base.H1_I),
        "Hsym_lower": np.asarray(base.Hsym_lower),
        "tree_edges": np.asarray(base.edges, dtype=np.int64),
        "angle_words": np.asarray(words, dtype=np.int64),
    }


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--points", required=True, help="state .npz with theta (B, 75) (and optionally Z)")
    ap.add_argument("--C", type=int, default=None, help="weight rank (default B)")
    ap.add_argument("--brot", type=int, default=10)
    ap.add_argument("--egap-target", type=float, default=3.918)
    ap.add_argument("--mu", type=float, default=0.0)
    ap.add_argument("--joint-iters", type=int, default=0, help="L-BFGS on (theta, w, W) with the full loss before quantising")
    ap.add_argument("--prog-batches", type=int, default=16)
    ap.add_argument("--prog-iters", type=int, default=30)
    ap.add_argument("--polish", type=int, default=2)
    ap.add_argument("--polish-rounds", type=int, default=1)
    ap.add_argument("--refine-rounds", type=int, default=0)
    ap.add_argument("--out", required=True)
    args = ap.parse_args()

    t0 = time.time()
    ref = dt.load_reference_cached()
    base, _ = dt.load_baseline()
    prob0 = rf.Problem(ref, base)
    z = np.load(args.points)
    theta = z["theta"]
    B = theta.shape[0]
    C = args.C or B
    u = rf.givens_forward(theta, base.edges)[0]
    if "Z" in z.files and z["Z"].shape == (B, B):
        Z = z["Z"]
    else:
        _, _, Z = varpro_value_grad(prob0, theta)
    w = weights_from_Z(Z, C)
    log(f"points B {B}, C {C}: projection error {1e3*projection_error(prob0, u):.3f} mHa")
    W = ls_offsets(prob0, u, w)
    fac = make_fac(base, w, W, u)
    prob = THCProblem(ref, fac, a_gap=10.0, egap_target=args.egap_target)
    prob.set_W(W)
    r = prob.forward_backward(theta, w, need_grad=False)
    log(f"rank-{C} weights, LS offsets: e2 {1e3*r['error_2']:.3f} mHa  E_gap {r['E_gap']:.4f}  negmass {r['negmass']:.3f}  "
        f"Lambda {r['Lambda']:.2f}  lam_eff {r['lambda_eff']:.3f}")
    W, r = solve_offsets(prob, theta, w, W, egap_target=args.egap_target, a_gap=10.0, mu=args.mu, iters=300)
    prob.set_W(W)
    if args.joint_iters:
        theta, w, W, r = lbfgs_thc(prob, theta, w, W, opt_theta=True, opt_w=True, opt_W=True, mu=args.mu,
                                   maxiter=args.joint_iters, tag="[joint]")
        prob.set_W(W)
    # quantisation (refit pipeline on this problem; W stays fixed inside it)
    prob.a_gap = 0.0
    words2 = rf.quantize_theta(theta, args.brot)[0]
    m, _ = rf.exact_eval(prob, words2, w.reshape(1, B, C), args.brot, one_body_sweeps=0)
    log(f"plain rounding brot {args.brot}: {dt.fmt(m)}")
    w3 = w.reshape(1, B, C)
    theta_q, w3 = rf.progressive(prob, theta, w3, args.brot, batches=args.prog_batches, iters=args.prog_iters)
    words2 = rf.quantize_theta(theta_q, args.brot)[0]
    for rnd in range(args.polish_rounds):
        words2 = rf.polish(prob, words2, w3, args.brot, sweeps=args.polish, max_moves=2)
        theta_q = words2 / (1 << (args.brot - 1))
        theta_q, w3, _ = rf.lbfgs(prob, theta_q, w3, opt_theta=False, opt_w=True, maxiter=60, tag=f"[w {rnd}]")
    if args.refine_rounds:
        theta_q, w3 = rf.refine(prob, theta_q, w3, args.brot, rounds=args.refine_rounds)
        words2 = rf.quantize_theta(theta_q, args.brot)[0]
        words2 = rf.polish(prob, words2, w3, args.brot, sweeps=args.polish, max_moves=2)
        theta_q = words2 / (1 << (args.brot - 1))
        theta_q, w3, _ = rf.lbfgs(prob, theta_q, w3, opt_theta=False, opt_w=True, maxiter=60, tag="[w final]")
    # re-steer E_gap with the final weights (W only), then exact metrics
    w = w3.reshape(B, C)
    W, r = solve_offsets(prob, theta_q, w, W, egap_target=args.egap_target, a_gap=10.0, mu=args.mu, iters=200, tag="[W final]")
    prob.set_W(W)
    m, words = rf.exact_eval(prob, words2, w3, args.brot, one_body_sweeps=8, verbose=True)
    log(f"final: {dt.fmt(m)}")
    u_q = rf.givens_forward(theta_q, base.edges)[0]
    arrays = submission_arrays(base, u_q, w, W, words)
    np.savez(args.out, theta=theta_q, w=w, W=W, brot=np.int64(args.brot), **{f"sub_{k}": v for k, v in arrays.items()})
    log(f"saved {args.out} ({time.time()-t0:.0f}s)")


# ---------------------------------------------------------------------------------------------
# Variable projection directly on the point coordinates u (B, N): the scale of u_b is absorbed by Z,
# so u is unconstrained; much better conditioned than the Givens angles.


def varpro_u_value_grad(prob, u: np.ndarray):
    Us = prob.sym.of_outer(u)
    Q, Rm = np.linalg.qr(Us.T)
    core = Q.T @ (prob.T @ Q)
    f = float(np.sum(prob.T * prob.T) - np.sum(core * core))
    Rinv = np.linalg.inv(Rm)
    Z = Rinv @ core @ Rinv.T
    ZUs = Z @ Us
    QtZ = Q.T @ ZUs.T
    dUs = 4.0 * (Q @ (core @ QtZ) - prob.T @ ZUs.T).T
    return f, prob.sym.grad_outer(dUs, u), Z


def varpro_u(prob, u: np.ndarray, maxiter: int = 500, tag: str = "", log=log):
    from scipy.optimize import minimize

    shape = u.shape
    state = {"calls": 0, "t0": time.time()}

    def fun(x):
        f, g, _ = varpro_u_value_grad(prob, x.reshape(shape))
        state["calls"] += 1
        if state["calls"] % 50 == 1:
            log(f"  varpro_u{tag} call {state['calls']:5d}  projection error {1e3*np.sqrt(max(f, 0)):8.3f} mHa  ({time.time()-state['t0']:.0f}s)")
        return f, g.ravel()

    res = minimize(fun, u.ravel(), jac=True, method="L-BFGS-B",
                   options={"maxiter": maxiter, "maxcor": 30, "ftol": 1e-15, "gtol": 1e-13})
    u = res.x.reshape(shape)
    u = u / np.linalg.norm(u, axis=1, keepdims=True)
    f, _, Z = varpro_u_value_grad(prob, u)
    log(f"  varpro_u{tag} done ({res.nit} it, {state['calls']} calls, {res.message}): projection error {1e3*np.sqrt(max(f, 0)):.3f} mHa")
    return u, Z, float(np.sqrt(max(f, 0)))


def grow_points(prob, u: np.ndarray, B_target: int, step: int = 8, iters: int = 60, log=log):
    """Greedy growth: add `step` points at a time (the top eigenvector dyads of the residual's dominant
    eigen-matrices), re-optimise all points with varpro_u for `iters` iterations."""
    u = u.copy()
    while u.shape[0] < B_target:
        Us = prob.sym.of_outer(u)
        Q, _ = np.linalg.qr(Us.T)
        core = Q.T @ (prob.T @ Q)
        Res = prob.T - Q @ core @ Q.T  # T - P T P
        ev, V = np.linalg.eigh(Res)
        idx = np.argsort(-np.abs(ev))[:step]
        new = []
        for k in idx:
            lam, E = np.linalg.eigh(prob.sym.to_matrix(V[:, k]))
            new.append(E[:, np.argmax(np.abs(lam))])
        u = np.concatenate([u, np.array(new)], axis=0)
        u, Z, err = varpro_u(prob, u, maxiter=iters, tag=f"[grow B{u.shape[0]}]")
        log(f"grow: B {u.shape[0]}  projection error {1e3*err:.3f} mHa")
    return u


def lbfgs_joint_u(prob: THCProblem, u, w, W, *, opt_u=True, opt_w=True, opt_W=True, mu=0.0, maxiter=300, tag="",
                  log=log):
    """L-BFGS on point coordinates u (unnormalised), weights w (B, C) and offsets W (C,) with the full loss."""
    from scipy.optimize import minimize

    parts = []
    if opt_u:
        parts.append(("u", u, 1.0))
    if opt_w:
        parts.append(("w", w, rf.W_SCALE))
    if opt_W:
        parts.append(("W", W, 1.0))
    x0 = np.concatenate([(arr / sc).ravel() for _, arr, sc in parts])
    state = {"calls": 0, "t0": time.time()}

    def unpack(x):
        vals = {"u": u, "w": w, "W": W}
        off = 0
        for name, arr, sc in parts:
            vals[name] = x[off:off + arr.size].reshape(arr.shape) * sc
            off += arr.size
        return vals

    def fun(x):
        v = unpack(x)
        r = prob.forward_backward_u(v["u"], v["w"], 0.0, mu, True, W=v["W"])
        state["calls"] += 1
        g = np.concatenate([(r["d" + name] * sc).ravel() for name, _, sc in parts])
        if state["calls"] % 50 == 1:
            log(f"  joint{tag} call {state['calls']:5d}  e2 {1e3*r['error_2']:8.3f} mHa  E_gap {r['E_gap']:.4f}  "
                f"Lambda {r['Lambda']:.2f} (L2 {r['lambda2']:.2f})  lam_eff {r['lambda_eff']:.3f}  loss {r['loss']:.4e}  ({time.time()-state['t0']:.0f}s)")
        return r["loss"], g

    res = minimize(fun, x0, jac=True, method="L-BFGS-B", options={"maxiter": maxiter, "maxcor": 30, "ftol": 1e-15, "gtol": 1e-13})
    v = unpack(res.x)
    r = prob.forward_backward_u(v["u"], v["w"], 0.0, mu, False, W=v["W"])
    log(f"  joint{tag} done ({res.nit} it, {state['calls']} calls, {res.message}): e2 {1e3*r['error_2']:.3f} mHa  "
        f"E_gap {r['E_gap']:.4f}  Lambda {r['Lambda']:.2f} (L2 {r['lambda2']:.2f})  lam_eff {r['lambda_eff']:.3f}")
    return v["u"], v["w"], v["W"], r


# ---------------------------------------------------------------------------------------------
# SOS-constrained THC: w = v*v (every column single-signed, X^c PSD) and W_c = -sum_b w_bc - t_c^2
# (W_c <= -tr X^c), so Lambda_2 = 1/4 sum W_c^2 exactly; the loss keeps only error_2^2 + a_gap (E_gap - target)^2.


def lbfgs_sos(prob: THCProblem, u, v, t, *, maxiter=300, tag="", log=log, opt_u=True):
    from scipy.optimize import minimize

    shapes = (u.shape, v.shape, t.shape)
    n_u = u.size if opt_u else 0
    x0 = np.concatenate([u.ravel() if opt_u else np.empty(0), v.ravel(), t.ravel()])
    state = {"calls": 0, "t0": time.time()}

    def unpack(x):
        uu = x[:n_u].reshape(shapes[0]) if opt_u else u
        vv = x[n_u:n_u + v.size].reshape(shapes[1])
        tt = x[n_u + v.size:].reshape(shapes[2])
        return uu, vv, tt

    def fun(x):
        uu, vv, tt = unpack(x)
        ww = vv * vv
        WW = -ww.sum(axis=0) - tt * tt
        r = prob.forward_backward_u(uu, ww, 0.0, 0.0, True, W=WW)
        state["calls"] += 1
        dW = r["dW"]
        dv = 2.0 * vv * (r["dw"] - dW[None, :])  # dW/dw_bc = -1
        dt_ = -2.0 * tt * dW
        g = np.concatenate([r["du"].ravel() if opt_u else np.empty(0), dv.ravel(), dt_.ravel()])
        if state["calls"] % 50 == 1:
            log(f"  sos{tag} call {state['calls']:5d}  e2 {1e3*r['error_2']:8.3f} mHa  E_gap {r['E_gap']:.4f}  "
                f"Lambda {r['Lambda']:.2f} (L2 {r['lambda2']:.2f})  lam_eff {r['lambda_eff']:.3f}  ({time.time()-state['t0']:.0f}s)")
        return r["loss"], g

    res = minimize(fun, x0, jac=True, method="L-BFGS-B", options={"maxiter": maxiter, "maxcor": 30, "ftol": 1e-15, "gtol": 1e-13})
    uu, vv, tt = unpack(res.x)
    ww = vv * vv
    WW = -ww.sum(axis=0) - tt * tt
    r = prob.forward_backward_u(uu, ww, 0.0, 0.0, False, W=WW)
    log(f"  sos{tag} done ({res.nit} it, {state['calls']} calls, {res.message}): e2 {1e3*r['error_2']:.3f} mHa  "
        f"E_gap {r['E_gap']:.4f}  Lambda {r['Lambda']:.2f}  lam_eff {r['lambda_eff']:.3f}")
    return uu, vv, tt, r


# ---------------------------------------------------------------------------------------------
# Levenberg-Marquardt / Gauss-Newton on the variable-projection residual with the Kaufman Jacobian
# (Z held at its optimum during each step), normal equations solved by CG with matrix-free products.
#   r(u) = T - U^T Z U,  J d = -(dU^T Z U + U^T Z dU),  dU_b = s(u_b d_b^T + d_b u_b^T),
#   J^T S = -2 grad_outer(Z U S, u)  (S symmetric).


def _dU(sym, u, d):
    """Directional derivative of s(u u^T) rows along d: s(u d^T + d u^T)."""
    return (u[:, sym.P] * d[:, sym.Q] + d[:, sym.P] * u[:, sym.Q]) * sym.scale


def gn_varpro(prob, u: np.ndarray, iters: int = 30, cg_iters: int = 20, lam: float = 1e-3, tag: str = "", log=log):
    sym = prob.sym
    T = prob.T
    f, g, Z = varpro_u_value_grad(prob, u)
    log(f"  gn{tag} start: projection error {1e3*np.sqrt(f):.3f} mHa")
    t0 = time.time()
    for it in range(iters):
        Us = sym.of_outer(u)
        ZU = Z @ Us  # (B, NPAIR)
        H = Us.T @ ZU
        r = T - H
        gradf = 4.0 * sym.grad_outer(ZU @ (H - T), u)  # = 2 J^T r
        rhs = -0.5 * gradf  # -J^T r

        def Jd(d):
            dU = _dU(sym, u, d)
            A = dU.T @ ZU
            return -(A + A.T)

        def JtS(S):
            return -2.0 * sym.grad_outer(ZU @ S, u)

        def JtJ(d):
            return JtS(Jd(d)) + lam * d

        # CG
        x = np.zeros_like(u)
        res = rhs - JtJ(x)
        p = res.copy()
        rs = np.sum(res * res)
        for k in range(cg_iters):
            Ap = JtJ(p)
            alpha = rs / max(np.sum(p * Ap), 1e-300)
            x += alpha * p
            res -= alpha * Ap
            rs_new = np.sum(res * res)
            if np.sqrt(rs_new) < 1e-10 * np.sqrt(np.sum(rhs * rhs)):
                break
            p = res + (rs_new / rs) * p
            rs = rs_new
        # trial step with VarPro re-solve
        u_try = u + x
        f_try, g_try, Z_try = varpro_u_value_grad(prob, u_try)
        if f_try < f:
            u, f, g, Z = u_try, f_try, g_try, Z_try
            lam = max(lam / 3.0, 1e-12)
            accepted = True
        else:
            lam *= 10.0
            accepted = False
        if it % 1 == 0:
            log(f"  gn{tag} it {it:3d}  projection error {1e3*np.sqrt(f):8.3f} mHa  lam {lam:.1e}  {'ok' if accepted else 'rejected'}  "
                f"cg {k+1}  ({time.time()-t0:.0f}s)")
    u = u / np.linalg.norm(u, axis=1, keepdims=True)
    f, _, Z = varpro_u_value_grad(prob, u)
    return u, Z, float(np.sqrt(max(f, 0)))


def symmetric_nmf(Z: np.ndarray, C: int, iters: int = 2000, seed: int = 0, log=log, tag: str = "") -> np.ndarray:
    """Nonnegative V (B, C) with V V^T ~ Z (entries of Z clipped at 0), multiplicative updates."""
    rng = np.random.default_rng(seed)
    Zp = np.clip(Z, 0, None)
    B = Z.shape[0]
    # init from the top-C eigenpairs (absolute values) scaled to the right norm
    lam, E = np.linalg.eigh(Zp)
    idx = np.argsort(-lam)[:C]
    V = np.abs(E[:, idx]) * np.sqrt(np.clip(lam[idx], 1e-12, None))[None, :]
    V += 1e-3 * V.mean() * rng.random(V.shape)
    beta = 0.5
    for it in range(iters):
        ZV = Zp @ V
        VVtV = V @ (V.T @ V)
        V = V * (1 - beta + beta * ZV / np.maximum(VVtV, 1e-300))
        if it % 500 == 0 or it == iters - 1:
            log(f"  snmf{tag} it {it:5d}: ||Z - VV^T|| / ||Z|| = {np.linalg.norm(Zp - V @ V.T) / np.linalg.norm(Zp):.4e}")
    return V


# ---------------------------------------------------------------------------------------------
# Levenberg-Marquardt on the full (u, w, W) problem for any (R, B, C): residuals R_H = T - H (Frobenius) and
# r_gap = sqrt(a_gap) (E_gap - target); matrix-free J / J^T products, CG on the damped normal equations.


def gn_joint(prob: THCProblem, u: np.ndarray, w: np.ndarray, W: np.ndarray, iters: int = 20, cg_iters: int = 20,
             lam: float = 1e-2, tag: str = "", log=log, opt_W: bool = True):
    sym = prob.sym
    R, B, C = w.shape
    sq = np.sqrt(prob.a_gap) if prob.a_gap else 0.0
    f_prev = None
    t0 = time.time()
    for it in range(iters):
        r = prob.forward_backward_u(u, w, 0.0, 0.0, True, W=W)
        f = r["loss"]
        if f_prev is None:
            log(f"  gnj{tag} start: e2 {1e3*r['error_2']:.3f} mHa  E_gap {r['E_gap']:.4f}  loss {f:.4e}")
        Us = r["Us"].reshape(R, B, -1)
        M = r["M"].reshape(R, C, -1)
        lam_h, V = r["lam"], r["V"]
        neg = lam_h < 0
        sP = sym.of_matrix(V[:, neg] @ V[:, neg].T)  # (NPAIR,)
        sPX = M @ sP  # (R, C) = <P_neg, X_rc>
        Wm = prob.Wmat

        def Jd(du, dw, dW):
            dUs = _dU(sym, u, du).reshape(R, B, -1)
            dM = np.matmul(dw.transpose(0, 2, 1), Us) + np.matmul(w.transpose(0, 2, 1), dUs)  # (R, C, NPAIR)
            dM2 = dM.reshape(R * C, -1)
            A = dM2.T @ r["M"]
            JH = -(A + A.T)
            dgap = 0.0
            if sq:
                dgap = float(np.sum(Wm * dW)) + 2.0 * (float(np.sum(dW * sPX)) + float(np.sum(Wm[:, :, None] * dM * sP)))
            return JH, sq * dgap

        def JtS(S, rho):
            SM = -2.0 * (r["M"] @ S).reshape(R, C, -1)  # adjoint of J_H on dM
            if sq:
                SM += (rho * sq * 2.0) * Wm[:, :, None] * sP[None, None, :]
            dw_adj = np.matmul(Us, SM.transpose(0, 2, 1))  # (R, B, C)
            dUs_adj = np.matmul(w, SM).reshape(R * B, -1)
            du_adj = sym.grad_outer(dUs_adj, u)
            dW_adj = (rho * sq) * (Wm + 2.0 * sPX) if sq else np.zeros_like(Wm)
            return du_adj, dw_adj, dW_adj

        def JtJ(du, dw, dW):
            S, rho = Jd(du, dw, dW)
            a, b, c = JtS(S, rho)
            return a + lam * du, b + lam * dw * (rf.W_SCALE ** -2) * 0 + lam * dw, (c + lam * dW) if opt_W else np.zeros_like(dW)

        rhs = (-0.5 * r["du"], -0.5 * r["dw"], (-0.5 * r["dW"]) if opt_W else np.zeros_like(W))
        x = tuple(np.zeros_like(v) for v in rhs)
        res = tuple(b - a for a, b in zip(JtJ(*x), rhs))
        p = tuple(v.copy() for v in res)
        rs = sum(np.sum(v * v) for v in res)
        rhs_norm = np.sqrt(sum(np.sum(v * v) for v in rhs))
        for k in range(cg_iters):
            Ap = JtJ(*p)
            pAp = sum(np.sum(a * b) for a, b in zip(p, Ap))
            alpha = rs / max(pAp, 1e-300)
            x = tuple(a + alpha * b for a, b in zip(x, p))
            res = tuple(a - alpha * b for a, b in zip(res, Ap))
            rs_new = sum(np.sum(v * v) for v in res)
            if np.sqrt(rs_new) < 1e-8 * rhs_norm:
                break
            p = tuple(a + (rs_new / rs) * b for a, b in zip(res, p))
            rs = rs_new
        u_t, w_t, W_t = u + x[0], w + x[1], (W + x[2]) if opt_W else W
        r_t = prob.forward_backward_u(u_t, w_t, 0.0, 0.0, False, W=W_t)
        if r_t["loss"] < f:
            u, w, W = u_t, w_t, W_t
            lam = max(lam / 3.0, 1e-10)
            ok = True
        else:
            lam *= 10.0
            ok = False
        f_prev = f
        log(f"  gnj{tag} it {it:3d}  e2 {1e3*(r_t if ok else r)['error_2']:8.3f} mHa  E_gap {(r_t if ok else r)['E_gap']:.4f}  "
            f"lam {lam:.1e} {'ok' if ok else 'rejected'} cg {k+1}  ({time.time()-t0:.0f}s)")
    prob.set_W(W)
    return u, w, W


# ---------------------------------------------------------------------------------------------
# Block variable projection for the grouped (R, B, C) factorisation: for fixed points the two-body operator is
# H = sum_r Us_r^T G_r Us_r, LINEAR in the per-group symmetric G_r = w_r w_r^T. The least-squares G solves
#   sum_r' K[r, r'] G_r' K[r', r] + ridge G_r = Us_r T Us_r^T,   K = Us Us^T (the dyad Gram),
# a symmetric positive system of R x B x B unknowns that CG applies in ~0.02 s. At the optimum the gradient in
# the points is the partial gradient with G fixed (Golub-Pereyra): 4 G Us (H - T) through grad_outer.


class BlockVarPro:
    def __init__(self, prob, R: int, B: int, ridge: float = 1e-8, cg_iters: int = 400, cg_tol: float = 1e-9):
        self.prob, self.R, self.B, self.ridge, self.cg_iters, self.cg_tol = prob, R, B, ridge, cg_iters, cg_tol
        self.G = None  # warm start (R, B, B)

    def solve_G(self, K: np.ndarray, Cm: np.ndarray) -> np.ndarray:
        R, B = self.R, self.B
        Kb = K.reshape(R, B, R, B).transpose(0, 2, 1, 3)  # (R, R', B, B): K[r, r'] blocks

        def apply(G):  # L(G)_r = sum_r' K[r,r'] G_r' K[r',r] + ridge G_r
            KG = np.einsum("rsab,sbc->rsac", Kb, G)  # K[r,s] G_s  (R, R', B, B)
            out = np.einsum("rsac,rscd->rad", KG, Kb.transpose(1, 0, 2, 3))  # ... K[s,r] = Kb[s, r]
            return out + self.ridge * G

        G = np.zeros_like(Cm) if self.G is None else self.G.copy()
        res = Cm - apply(G)
        p = res.copy()
        rs = np.sum(res * res)
        bnorm = np.sqrt(np.sum(Cm * Cm))
        for k in range(self.cg_iters):
            Ap = apply(p)
            alpha = rs / max(np.sum(p * Ap), 1e-300)
            G += alpha * p
            res -= alpha * Ap
            rs_new = np.sum(res * res)
            if np.sqrt(rs_new) < self.cg_tol * bnorm:
                break
            p = res + (rs_new / rs) * p
            rs = rs_new
        G = 0.5 * (G + G.transpose(0, 2, 1))
        self.G = G
        self.cg_used = k + 1
        return G

    def value_grad(self, u: np.ndarray, need_grad: bool = True):
        prob, R, B = self.prob, self.R, self.B
        sym, T = prob.sym, prob.T
        Us = sym.of_outer(u)  # (R*B, NPAIR)
        K = Us @ Us.T
        TU = T @ Us.T  # (NPAIR, R*B)
        Cm = np.stack([Us[r * B:(r + 1) * B] @ TU[:, r * B:(r + 1) * B] for r in range(R)])  # (R, B, B)
        Cm = 0.5 * (Cm + Cm.transpose(0, 2, 1))
        G = self.solve_G(K, Cm)
        GU = np.concatenate([G[r] @ Us[r * B:(r + 1) * B] for r in range(R)], axis=0)  # (R*B, NPAIR)
        H = Us.T @ GU
        Res = H - T
        f = float(np.sum(Res * Res))
        if not need_grad:
            return f, None, G
        dUs = 4.0 * (GU @ Res)
        return f, sym.grad_outer(dUs, u), G


def block_varpro_points(prob, u: np.ndarray, R: int, B: int, maxiter: int = 200, ridge: float = 1e-8, tag: str = "",
                        log=log, bvp: BlockVarPro | None = None):
    from scipy.optimize import minimize

    bvp = bvp or BlockVarPro(prob, R, B, ridge=ridge)
    shape = u.shape
    state = {"calls": 0, "t0": time.time()}

    def fun(x):
        f, g, _ = bvp.value_grad(x.reshape(shape))
        state["calls"] += 1
        if state["calls"] % 20 == 1:
            log(f"  bvp{tag} call {state['calls']:5d}  e2 {1e3*np.sqrt(max(f, 0)):8.3f} mHa  cg {bvp.cg_used}  ({time.time()-state['t0']:.0f}s)")
        return f, g.ravel()

    res = minimize(fun, u.ravel(), jac=True, method="L-BFGS-B",
                   options={"maxiter": maxiter, "maxcor": 30, "ftol": 1e-15, "gtol": 1e-13})
    u = res.x.reshape(shape)
    f, _, G = bvp.value_grad(u, need_grad=False)
    log(f"  bvp{tag} done ({res.nit} it, {state['calls']} calls, {res.message}): e2 {1e3*np.sqrt(max(f, 0)):.3f} mHa")
    return u, G, float(np.sqrt(max(f, 0)))


def weights_from_G(G: np.ndarray, C: int):
    """PSD rank-C factor of every block: w (R, B, C)."""
    R, B, _ = G.shape
    w = np.zeros((R, B, C))
    for r in range(R):
        lam, E = np.linalg.eigh(G[r])
        idx = np.argsort(-lam)[:C]
        w[r] = E[:, idx] * np.sqrt(np.clip(lam[idx], 0, None))[None, :]
    return w


# ======================================================================
# prune.py
# ======================================================================

"""Within-group point pruning of the DF-THC factorisation: (65, 60, C) -> (65, B', C).

The lookup cost is ~proportional to A = 76 + R B and the inner PREPARE drops a QROAM level at B <= 31 (its temporary
qubits then fall below the outer PREPARE's 370, like the brot <= 7 cliff), so fewer points per group pay twice:
(65, 31, 45) is worth 2.3x, (65, 24, 45) 2.8x, (65, 16, 45) 3.8x at brot 10 / J 10 if the accuracy survives (cost
table in notes.md §8). Each stage keeps the B' points of largest weight energy sum_c w_bc^2 in every group and
re-optimises points, weights and offsets with the full loss (error_2^2 + a_gap (E_gap - target)^2 + mu Lambda_2)
through `thc_fit.THCProblem`, which handles any (R, B, C).

    python tasks/dfthcsos/prune.py --init baseline --B 40 --iters 500 --out build/prune_B40.npz
    python tasks/dfthcsos/prune.py --init build/prune_B40.npz --B 32 --iters 800 --out build/prune_B32.npz
"""

import argparse
import os
import sys
import time

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

N = dt.N
log = rf.log


def load_state(path: str, base: dt.Factorization):
    """u (R, B, N) unit rows, w (R, B, C), W (R, C) from 'baseline' or a prune/refit state file."""
    if path == "baseline":
        u = base.U / np.linalg.norm(base.U, axis=2, keepdims=True)
        return u, base.w.copy(), base.W.copy()
    with np.load(path) as z:
        if "u" in z.files and z["u"].ndim == 3:
            return z["u"], z["w"], z["W"]
        # a refit.py state (theta, w) with the baseline's W
        theta = z["theta"]
        w = z["w"]
        R, B, C = w.shape
        u = dt.decode(dt.quantize(theta, 20), 20, base.edges) if theta.max() <= 2 else theta
        return u.reshape(R, B, N), w, base.W.copy()


def prune_points(u: np.ndarray, w: np.ndarray, B_new: int):
    R, B, C = w.shape
    energy = np.sum(w ** 2, axis=2)  # (R, B)
    keep = np.argsort(-energy, axis=1)[:, :B_new]
    keep.sort(axis=1)
    u2 = np.take_along_axis(u, keep[:, :, None], axis=1)
    w2 = np.take_along_axis(w, keep[:, :, None], axis=1)
    return u2, w2, keep


def group_contributions(prob, u: np.ndarray, w: np.ndarray) -> np.ndarray:
    """||sum_c X_rc (x) X_rc||_F per group = ||M_r M_r^T||_F with M_r = s(X_rc) rows (R,)."""
    R, B, C = w.shape
    Us = prob.sym.of_outer(u.reshape(-1, N)).reshape(R, B, -1)
    M = np.matmul(w.transpose(0, 2, 1), Us)  # (R, C, NPAIR)
    return np.array([np.linalg.norm(M[r] @ M[r].T) for r in range(R)])


def prune_groups(prob, u: np.ndarray, w: np.ndarray, W: np.ndarray, R_new: int):
    """Keep the R_new groups with the largest contribution to the two-body operator."""
    contrib = group_contributions(prob, u, w)
    keep = np.sort(np.argsort(-contrib)[:R_new])
    log(f"dropping groups {sorted(set(range(len(contrib))) - set(keep.tolist()))} (contributions "
        f"{np.round(np.sort(contrib)[:len(contrib)-R_new], 4).tolist()} of max {contrib.max():.3f})")
    return u[keep], w[keep], W[keep]


def prune_columns(w: np.ndarray, W: np.ndarray, C_new: int):
    R, B, C = w.shape
    energy = np.sum(w ** 2, axis=1)  # (R, C)
    keep = np.argsort(-energy, axis=1)[:, :C_new]
    keep.sort(axis=1)
    w2 = np.take_along_axis(w, keep[:, None, :], axis=2)
    W2 = np.take_along_axis(W, keep, axis=1)
    return w2, W2


def normalise_state(uu: np.ndarray, w: np.ndarray):
    """Unit rows with the norms absorbed into the weights: s(u u^T) = |u|^2 s(n n^T), so w_bc -> w_bc |u_b|^2."""
    R, B, C = w.shape
    norms = np.linalg.norm(uu.reshape(R * B, N), axis=1)
    u = (uu.reshape(R * B, N) / norms[:, None]).reshape(R, B, N)
    w = w * (norms ** 2).reshape(R, B, 1)
    return u, w


def make_problem(ref, base, u, w, W, egap_target: float, a_gap: float) -> tf.THCProblem:
    R, B, C = w.shape
    fac = dt.Factorization(w=w, W=W, S=base.S, beta_1=base.beta_1, edges=base.edges, U=u, H1_I=base.H1_I,
                           Hsym_lower=base.Hsym_lower)
    prob = tf.THCProblem(ref, fac, a_gap=a_gap, egap_target=egap_target)
    prob.set_W(W)
    return prob


def report(prob, u, w, W, label: str):
    r = prob.forward_backward_u(u.reshape(-1, N), w, 0.0, 0.0, False, W=W)
    log(f"{label}: e2 {1e3*r['error_2']:.3f} mHa  E_gap {r['E_gap']:.5f}  negmass {r['negmass']:.3f}  "
        f"Lambda {r['Lambda']:.3f} (L2 {r['lambda2']:.3f})  lam_eff {r['lambda_eff']:.4f}")
    return r


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--init", default="baseline")
    ap.add_argument("--B", type=int, default=None, help="points per group to keep (default: unchanged)")
    ap.add_argument("--R", type=int, default=None, help="groups to keep (default: unchanged)")
    ap.add_argument("--C", type=int, default=None, help="columns per group to keep (default: unchanged)")
    ap.add_argument("--iters", type=int, default=500)
    ap.add_argument("--mu", type=float, default=0.0)
    ap.add_argument("--a-gap", type=float, default=10.0)
    ap.add_argument("--egap-target", type=float, default=3.918)
    ap.add_argument("--w-first", type=int, default=0, help="iterations on (w, W) only before the joint refit")
    ap.add_argument("--out", required=True)
    args = ap.parse_args()

    t0 = time.time()
    ref = dt.load_reference_cached()
    base, _ = dt.load_baseline()
    u, w, W = load_state(args.init, base)
    prob = make_problem(ref, base, u, w, W, args.egap_target, args.a_gap)
    report(prob, u, w, W, f"init {args.init} {w.shape}")
    if args.C and args.C < w.shape[2]:
        w, W = prune_columns(w, W, args.C)
    if args.R and args.R < w.shape[0]:
        u, w, W = prune_groups(prob, u, w, W, args.R)
    if args.B and args.B < w.shape[1]:
        u, w, keep = prune_points(u, w, args.B)
    prob = make_problem(ref, base, u, w, W, args.egap_target, args.a_gap)
    report(prob, u, w, W, f"pruned to {w.shape}")
    uu = u.reshape(-1, N)
    if args.w_first:
        uu, w, W, r = tf.lbfgs_joint_u(prob, uu, w, W, opt_u=False, opt_w=True, opt_W=True, mu=args.mu,
                                       maxiter=args.w_first, tag=f"[{w.shape} w,W]")
    uu, w, W, r = tf.lbfgs_joint_u(prob, uu, w, W, opt_u=True, opt_w=True, opt_W=True, mu=args.mu,
                                   maxiter=args.iters, tag=f"[{w.shape}]")
    u, w = normalise_state(uu, w)
    r = report(prob, u, w, W, f"final {w.shape}")
    np.savez(args.out, u=u, w=w, W=W, theta=dt.decompose(u.reshape(-1, N), base.edges),
             metrics=np.array([r["error_2"], r["E_gap"], r["Lambda"], r["lambda_eff"]]))
    log(f"saved {args.out} ({time.time()-t0:.0f}s)")




# ======================================================================
# train_mps.py
# ======================================================================

"""Adam training of the grouped DF-THC factorisation in PyTorch (MPS or CPU), with progressive group dropping.

Variables: points u (R*B, N) (unnormalised: the dyad scale is absorbed by the weights and divided out when a
state is saved), weights w (R, B, C), offsets W (R, C).  Loss (float32 on the device):
    error_2^2 + a_gap (E_gap - target)^2 + beta D(w) + mu Lambda_2
with D(w) = 1/2 sum_rc [(sum_b |w|)^2 - (sum_b w)^2] (zero iff every column is single-signed) and the verifier's
E_gap = E_UPPER - ecore + eta beta_1 + 1/2 sum W^2 + 2 negmass(h1'), h1' = h1_base - sum_rc W_rc X_rc (eigvalsh on a
76 x 76 matrix).  Every `eval_every` steps the state is evaluated in float64 with the verifier's own metric code
(dfthc_tools / refit.Problem) and the best state of the stage is kept.  Between stages the groups with the smallest
contribution ||sum_c X_rc (x) X_rc||_F are dropped.  Each stage checkpoints to <out-prefix>R<R>.npz (u normalised,
w rescaled, W), loadable by prune.load_state / quantize_state.py.

    python3 tasks/dfthcsos/train_mps.py --device mps --bench 100
    python3 tasks/dfthcsos/train_mps.py --device mps --schedule 60,55,48,42,36,32,28,26 --steps 100000 --out-prefix build/mps_
"""

import argparse
import os
import sys
import time

import numpy as np
import torch

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

N = dt.N
log = rf.log


class Trainer:
    def __init__(self, ref, base, u, w, W, device: str, a_gap: float, egap_target: float, beta: float, mu: float):
        self.ref, self.base = ref, base
        self.dev = torch.device(device)
        self.dtype = torch.float32
        sym = rf.Sym()
        self.P = torch.tensor(sym.P, device=self.dev)
        self.Q = torch.tensor(sym.Q, device=self.dev)
        self.scale = torch.tensor(sym.scale, device=self.dev, dtype=self.dtype)
        prob0 = rf.Problem(ref, base)
        self.T = torch.tensor(prob0.T, device=self.dev, dtype=self.dtype)
        self.h1_base = torch.tensor(prob0.h1_base, device=self.dev, dtype=self.dtype)
        self.c_gap = float(dt.E_UPPER - ref["ecore"] + ref["electrons"] * base.beta_1)  # E_gap = c_gap + 0.5 sum W^2 + 2 negmass
        self.sym_np = sym
        self.a_gap, self.egap_target, self.beta, self.mu = a_gap, egap_target, beta, mu
        self.set_state(u, w, W)

    def set_state(self, u, w, W):
        R, B, C = w.shape
        self.R, self.B, self.C = R, B, C
        self.u = torch.tensor(np.asarray(u).reshape(R * B, N), device=self.dev, dtype=self.dtype, requires_grad=True)
        self.w = torch.tensor(np.asarray(w), device=self.dev, dtype=self.dtype, requires_grad=True)
        self.W = torch.tensor(np.asarray(W), device=self.dev, dtype=self.dtype, requires_grad=True)

    def forward(self, need_parts: bool = False):
        u, w, W = self.u, self.w, self.W
        R, B, C = self.R, self.B, self.C
        Us = (u[:, self.P] * u[:, self.Q] * self.scale).reshape(R, B, -1)  # (R, B, NPAIR)
        M = torch.bmm(w.transpose(1, 2), Us)  # (R, C, NPAIR)
        M2 = M.reshape(R * C, -1)
        H = M2.T @ M2
        L2 = ((H - self.T) ** 2).sum()
        # one-body absorption and E_gap
        z = (W.reshape(R * C, 1) * M2).sum(dim=0) / self.scale  # unscaled pair vector
        h1 = self.h1_base.clone()
        h1 = h1.index_put((self.P, self.Q), self.h1_base[self.P, self.Q] - z)
        h1 = h1.index_put((self.Q, self.P), self.h1_base[self.Q, self.P] - z)
        lam = torch.linalg.eigvalsh(h1)
        negmass = -torch.clamp(lam, max=0.0).sum()
        E_gap = self.c_gap + 0.5 * (W ** 2).sum() + 2.0 * negmass
        s = w.sum(dim=1)  # (R, C)
        l1 = w.abs().sum(dim=1)
        D = 0.5 * ((l1 ** 2) - (s ** 2)).sum()
        lam2 = 0.25 * ((l1 + (W + s).abs()) ** 2).sum()
        loss = L2 + self.a_gap * (E_gap - self.egap_target) ** 2 + self.beta * D + self.mu * lam2
        if need_parts:
            Lambda = lam.abs().sum() + lam2
            return loss, dict(L2=L2, E_gap=E_gap, negmass=negmass, D=D, lam2=lam2, Lambda=Lambda,
                              lam_eff=torch.sqrt(torch.clamp(E_gap * (2 * Lambda - E_gap), min=0.0)), M=M.detach())
        return loss, None

    def numpy_state(self):
        u = self.u.detach().cpu().numpy().astype(np.float64)
        w = self.w.detach().cpu().numpy().astype(np.float64)
        W = self.W.detach().cpu().numpy().astype(np.float64)
        un, wn = pr.normalise_state(u, w)
        return un, wn, W

    def evaluate64(self):
        """Verifier metrics in float64 (continuous rows)."""
        u, w, W = self.numpy_state()
        prob = pr.make_problem(self.ref, self.base, u, w, W, self.egap_target, 0.0)
        r = prob.forward_backward_u(u.reshape(-1, N), w, 0.0, 0.0, False, W=W)
        return {k: float(r[k]) for k in ("error_2", "E_gap", "negmass", "Lambda", "lambda2", "lambda_eff")}

    def drop_groups(self, R_new: int):
        with torch.no_grad():
            _, parts = self.forward(need_parts=True)
            M = parts["M"]
            contrib = torch.stack([torch.linalg.norm(M[r] @ M[r].T) for r in range(self.R)]).cpu().numpy()
        keep = np.sort(np.argsort(-contrib)[:R_new])
        log(f"dropping {self.R - R_new} groups (contributions {np.round(np.sort(contrib)[:self.R-R_new], 4).tolist()})")
        u = self.u.detach().cpu().numpy().reshape(self.R, self.B, N)[keep]
        w = self.w.detach().cpu().numpy()[keep]
        W = self.W.detach().cpu().numpy()[keep]
        self.set_state(u, w, W)

    def train_stage(self, steps: int, lr0: float, lr1: float, eval_every: int, tag: str, w_lr_scale: float = 1.0):
        params = [{"params": [self.u], "lr": lr0}, {"params": [self.w], "lr": lr0 * w_lr_scale}, {"params": [self.W], "lr": lr0}]
        opt = torch.optim.Adam(params)
        best = None
        t0 = time.time()
        for step in range(steps + 1):
            frac = step / max(steps, 1)
            lr = lr1 + 0.5 * (lr0 - lr1) * (1 + np.cos(np.pi * frac))  # cosine decay lr0 -> lr1
            for g, sc in zip(opt.param_groups, (1.0, w_lr_scale, 1.0)):
                g["lr"] = lr * sc
            if step % eval_every == 0 or step == steps:
                m = self.evaluate64()
                dt_s = time.time() - t0
                log(f"{tag} step {step:7d}  lr {lr:.2e}  e2 {1e3*m['error_2']:8.3f} mHa  E_gap {m['E_gap']:.4f}  "
                    f"Lambda {m['Lambda']:.2f}  lam_eff {m['lambda_eff']:.3f}  ({dt_s:.0f}s, {step/max(dt_s,1e-9):.1f} steps/s)")
                if best is None or m["error_2"] < best[0]:
                    best = (m["error_2"], self.numpy_state(), m)
            if step == steps:
                break
            opt.zero_grad(set_to_none=True)
            loss, _ = self.forward()
            loss.backward()
            opt.step()
        return best


def save_state(path: str, u, w, W, metrics: dict, base):
    np.savez(path, u=u, w=w, W=W, theta=dt.decompose(u.reshape(-1, N), base.edges),
             metrics=np.array([metrics["error_2"], metrics["E_gap"], metrics["Lambda"], metrics["lambda_eff"]]))


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--init", default="baseline")
    ap.add_argument("--C", type=int, default=45)
    ap.add_argument("--device", default="mps")
    ap.add_argument("--schedule", default="60,55,48,42,36,32,28,26", help="group counts after each drop")
    ap.add_argument("--steps", type=int, default=100000, help="Adam steps per stage")
    ap.add_argument("--steps-first", type=int, default=None, help="steps for the first stage (default: --steps)")
    ap.add_argument("--lr", type=float, default=1e-3, help="Adam lr for points and offsets (cosine decay to --lr-end)")
    ap.add_argument("--lr-end", type=float, default=1e-5)
    ap.add_argument("--w-lr-scale", type=float, default=0.01, help="weights are ~0.0025: their lr is this fraction of --lr")
    ap.add_argument("--a-gap", type=float, default=10.0)
    ap.add_argument("--egap-target", type=float, default=3.918)
    ap.add_argument("--beta", type=float, default=0.0, help="weight of the semidefiniteness penalty D(w)")
    ap.add_argument("--mu", type=float, default=0.0)
    ap.add_argument("--eval-every", type=int, default=2000)
    ap.add_argument("--bench", type=int, default=0, help="time this many steps and exit")
    ap.add_argument("--out-prefix", default="build/mps_")
    ap.add_argument("--seed", type=int, default=0)
    args = ap.parse_args()

    torch.manual_seed(args.seed)
    np.random.seed(args.seed)
    ref = dt.load_reference_cached()
    base, _ = dt.load_baseline()
    u, w, W = pr.load_state(args.init, base)
    if args.C and args.C < w.shape[2]:
        w, W = pr.prune_columns(w, W, args.C)
    tr = Trainer(ref, base, u, w, W, args.device, args.a_gap, args.egap_target, args.beta, args.mu)
    m = tr.evaluate64()
    log(f"init {args.init} {w.shape} on {args.device}: e2 {1e3*m['error_2']:.3f} mHa  E_gap {m['E_gap']:.4f}  Lambda {m['Lambda']:.2f}")
    if args.bench:
        opt = torch.optim.Adam([tr.u, tr.w, tr.W], lr=1e-6)
        for _ in range(3):
            opt.zero_grad(); loss, _ = tr.forward(); loss.backward(); opt.step()
        if args.device == "mps":
            torch.mps.synchronize()
        t0 = time.time()
        for _ in range(args.bench):
            opt.zero_grad(); loss, _ = tr.forward(); loss.backward(); opt.step()
        if args.device == "mps":
            torch.mps.synchronize()
        dt_s = time.time() - t0
        log(f"bench {args.device}: {args.bench} Adam steps in {dt_s:.1f}s = {args.bench/dt_s:.2f} steps/s ({1e3*dt_s/args.bench:.0f} ms/step)")
        return
    schedule = [int(x) for x in args.schedule.split(",") if x]
    for i, R_new in enumerate(schedule):
        if R_new < tr.R:
            tr.drop_groups(R_new)
            m = tr.evaluate64()
            log(f"after drop -> R {tr.R}: e2 {1e3*m['error_2']:.3f} mHa  E_gap {m['E_gap']:.4f}")
        steps = args.steps_first if (i == 0 and args.steps_first) else args.steps
        best = tr.train_stage(steps, args.lr, args.lr_end, args.eval_every, tag=f"[R{tr.R}]", w_lr_scale=args.w_lr_scale)
        err, (u, w, W), m = best
        out = f"{args.out_prefix}R{tr.R}.npz"
        save_state(out, u, w, W, m, base)
        log(f"stage R {tr.R} best e2 {1e3*err:.3f} mHa  E_gap {m['E_gap']:.4f}  Lambda {m['Lambda']:.2f}  lam_eff {m['lambda_eff']:.3f} -> {out}")
        tr.set_state(u, w, W)




if __name__ == "__main__":
    if ON_KAGGLE and len(sys.argv) == 1:
        sys.argv += ["--device", "cuda", "--out-prefix", "/kaggle/working/stage_", "--init", os.environ.get("VQCC_INIT", "baseline"),
                     "--schedule", os.environ.get("VQCC_SCHEDULE", "60,55,48,42,36,32,28,26"),
                     "--steps", os.environ.get("VQCC_STEPS", "100000"), "--eval-every", "2000"]
    main()
